{"function":"() => {
  const items = [];
  // Find all SKU links or rows
  const skuLinks = Array.from(document.querySelectorAll('a[href*="skucentral?mSku="]'));
  skuLinks.forEach(link => {
    const sku = link.innerText.trim();
    // find container
    let container = link.parentElement;
    for (let i = 0; i < 8 && container; i++) {
      if (container.querySelector('input[type="text"], input[required]')) break;
      container = container.parentElement;
    }
    const text = container ? container.innerText : "";
    const asinMatch = text.match(/(?:ASIN|FNSKU)[:\s\n]+([A-Z0-9]{10})/i);
    const stockMatch = text.match(/(\d+)\s*(?:可售|件)/);
    const priceInput = container ? container.querySelector('input[required]') : null;
    const priceValue = priceInput ? priceInput.value : null;

    items.push({
      sku,
      asin: asinMatch ? asinMatch[1] : null,
      price: priceValue,
      stockText: stockMatch ? stockMatch[0] : null,
      hasInput: !!priceInput,
      snippet: text.split('\n').filter(s => s.trim().length > 0).slice(0, 15)
    });
  });

  return items;
}","pageId":1,"toolSummary":"Extract 30315 items info","waitForStableDom":false}

