{"function":"() => {
  const result = [];
  ['4A GM30315', '4A 30315'].forEach(targetSku => {
    // Find the link matching targetSku exactly
    const links = Array.from(document.querySelectorAll('a')).filter(a => a.innerText.trim() === targetSku);
    links.forEach(a => {
      // Find row
      let el = a;
      while (el && el.tagName !== 'TR' && !el.getAttribute('data-testid')?.includes('row') && el.parentElement) {
        el = el.parentElement;
      }

      const inputs = Array.from(el.querySelectorAll('input')).map(inp => ({
        uid: inp.getAttribute('data-uid') || inp.id || inp.name,
        type: inp.type,
        value: inp.value,
        outerHTML: inp.outerHTML.slice(0, 150)
      }));

      const buttons = Array.from(el.querySelectorAll('button, a')).map(b => ({
        text: b.innerText.trim(),
        ariaLabel: b.getAttribute('aria-label'),
        href: b.href
      })).filter(b => b.text || b.ariaLabel);

      result.push({
        sku: targetSku,
        inputs,
        buttons: buttons.slice(0, 10)
      });
    });
  });
  return result;
}","pageId":1,"toolSummary":"Inspect price input and buttons for target SKUs","waitForStableDom":false}

