{"function":"() => {
  function findInputs(root) {
    let results = [];
    if (!root) return results;
    if (root.querySelectorAll) {
      const inputs = root.querySelectorAll('input[type="file"]');
      results.push(...Array.from(inputs));
    }
    const children = root.querySelectorAll ? Array.from(root.querySelectorAll('*')) : [];
    for (const el of children) {
      if (el.shadowRoot) {
        results.push(...findInputs(el.shadowRoot));
      }
    }
    return results;
  }
  const fileInputs = findInputs(document);
  return fileInputs.map(i => ({
    tagName: i.tagName,
    id: i.id,
    name: i.name,
    accept: i.accept,
    className: i.className,
    disabled: i.disabled,
    parentTag: i.parentElement ? i.parentElement.tagName : null
  }));
