  const reviewCount = document.querySelector('#acrCustomerReviewText') ? document.querySelector('#acrCustomerReviewText').innerText.trim() : null;

  // Also check buybox and all price elements
  const allPrices = Array.from(document.querySelectorAll('.a-price .a-offscreen')).map(p => p.innerText.trim()).filter(Boolean);

